# 3. ORF finding in all six frames
def find_orfs(seq, min_len=100):
    stop_codons = {'TAA', 'TAG', 'TGA'}
    start_codons = {'ATG'}
    orfs = []
    frames = [(seq, '+'), (seq, '-')]
    for strand, strand_name in frames:
        length = len(strand)
        for frame in range(3):
            i = frame
            while i < length - 2:
                codon = strand[i:i+3]
                if codon in start_codons:
                    # Start of potential ORF
                    for j in range(i, length - 2, 3):
                        codon_j = strand[j:j+3]
                        if codon_j in stop_codons:
                            if (j - i) > min_len * 3:
                                orfs.append({
                                    'strand': strand_name,
                                    'frame': frame + 1,
                                    'start': i + 1,   # 1-based
                                    'end': j + 3,     # inclusive of stop
                                    'length_aa': (j - i) // 3,
                                })
                            i = j
                            break
                    else:
                        # Truncated at end of sequence
                        if (length - i) > min_len * 3:
                            orfs.append({
                                'strand': strand_name,
                                'frame': frame + 1,
                                'start': i + 1,
                                'end': None,  # no stop codon found
                                'length_aa': (length - i) // 3,
                            })
                        i = length
                else:
                    i += 3
    return orfs

def reverse_complement(s):
    comp = {'A': 'T', 'T': 'A', 'C': 'G', 'G': 'C', 'N': 'N'}
    return ''.join(comp[c] for c in reversed(s))

rc = reverse_complement(sequence)

orfs = find_orfs(sequence, min_len=50)
orfs_rc = find_orfs(rc, min_len=50)

# Convert reverse-complement coordinates back to forward strand coords
for o in orfs_rc:
    fwd_start = len(sequence) - o['end'] + 1 if o['end'] else None
    fwd_end = len(sequence) - o['start'] + 1
    o['strand'] = '-'
    o['forward_start'] = fwd_start
    o['forward_end'] = fwd_end

all_orfs = sorted(orfs + orfs_rc, key=lambda x: x['length_aa'], reverse=True)
print(f"Total ORFs >= 50 aa: {len(all_orfs)}")
print("\nTop ORFs by length:")
for o in all_orfs[:10]:
    if o['strand'] == '+':
        print(f"  Strand {o['strand']}, frame {o['frame']}, "
              f"coords {o['start']}-{o['end']} (or truncated), "
              f"length {o['length_aa']} aa")
    else:
