def find_orfs(seq, min_aa=50):
    stops = {'TAA', 'TAG', 'TGA'}
    starts = {'ATG'}
    orfs = []
    for strand_name, s in [('+', seq), ('-', reverse_complement(seq))]:
        n = len(s)
        for frame in range(3):
