                        if s[j:j+3] in stops:
                            if (j - i) // 3 + 1 >= min_aa:
                                orfs.append((strand_name, frame+1, s, i, j+2, True, (j - i)//3 + 1))
                            i = j
                            found_stop = True
                            break
                    if not found_stop:
                        if (n - i) // 3 >= min_aa:
                            orfs.append((strand_name, frame+1, s, i, None, False, (n - i)//3))
