# Also look for a stem-loop / hairpin-terminated inverted repeat (terminator-like)
# Search for palindromic stretches of >= 10 bp separated by a small loop
def find_inverted_repeats(seq, min_stem=10, max_loop=10):
    results = []
    L = len(seq)
    comp = {'A':'T','T':'A','C':'G','G':'C','N':'N'}
    for i in range(L - 2*min_stem - max_loop):
        for loop in range(1, max_loop + 1):
            stem = min_stem
            while True:
                # extend stem
                if i + stem - 1 + loop + stem - 1 < L:
                    left = seq[i + stem - 1]
                    right = comp.get(seq[i + stem - 1 + loop], 'N')
                    if left == right and stem < 20:
                        stem += 1
                    else:
                        break
                else:
                    break
            if stem >= min_stem:
                results.append((i+1, i+stem-1, loop, stem-1))
    return results

