def tm_segments(aa_seq, window=19, threshold=1.6):
    vals = [kd.get(a, 0) for a in aa_seq]
    segs = []
    in_seg = False
    for i in range(0, len(vals) - window + 1):
        avg = sum(vals[i:i+window])/window
        if avg > threshold:
            if not in_seg:
                seg_start = i
                in_seg = True
        else:
            if in_seg:
                segs.append((seg_start+1, i+window-1, max(sum(vals[j:j+window])/window for j in range(seg_start, i+1))))
                in_seg = False
    if in_seg:
        segs.append((seg_start+1, len(vals)-window+window, max(sum(vals[j:j+window])/window for j in range(seg_start, len(vals)-window+1))))
    return segs

